30	/**
31	 * Simple JavaBean domain object representing an owner.
32	 *
33	 * @author Ken Krebs
34	 * @author Juergen Hoeller
35	 * @author Sam Brannen
36	 * @author Michael Isvy
37	 */
38	@Entity
39	@Table(name = "owners")
40	public class Owner extends Person {
41	    @Column(name = "title")
42	    private String title;
43	
44	    @Column(name = "address")
45	    private String address;
46	
47	    @Column(name = "address_line1")
48	    private String addressLine1;
49	
50	    @Column(name = "address_line2")
51	    private String addressLine2;
52	
53	    @Column(name = "city")
54	    @NotEmpty
55	    private String city;
56	
57	    @Column(name = "postcode")
58	    private String postcode;
59	
60	    @Column(name = "telephone")
61	    @NotEmpty
62	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
63	    private String telephone;
64	
65	    @Column(name = "email")
66	    @Email
67	    private String email;
68	
69	    @Column(name = "registration_date", columnDefinition = "DATE")
70	    private LocalDate registrationDate;
71	
72	    @Column(name = "birth_date", columnDefinition = "DATE")
73	    private LocalDate birthDate;
74	
75	    @Column(name = "customer_code")
76	    private String customerCode;
77	
78	    @Column(name = "membership_number")
79	    private String membershipNumber;
80	
81	    @Column(name = "household_id")
82	    private String householdId;
83	
84	    @Column(name = "namesake_count")
85	    private Integer namesakeCount;
86	
87	    @Column(name = "bulk_signup_warning")
88	    private boolean bulkSignupWarning;
89	
90	    @Column(name = "household_member_count")
91	    private Integer householdMemberCount;
92	
93	    @Column(name = "possible_duplicate")
94	    private boolean possibleDuplicate;
95	
96	    @Column(name = "possible_duplicate_of")
97	    private Integer possibleDuplicateOf;
98	
99	    @Column(name = "deleted")
100	    private boolean deleted;
101	
102	    @Column(name = "idempotency_key")
103	    private String idempotencyKey;
104	
105	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
106	    private Set<Pet> pets;
107	
108	    /**
109	     * Transient, write-only request flag: when {@code true}, creating this owner is allowed even if
110	     * another owner already shares the same last name and address. Never persisted or returned.
111	     */
112	    @Transient
113	    private boolean sharesHousehold;
114	
115	    public String getTitle() {
116	        return this.title;
117	    }
118	
119	    public void setTitle(String title) {
120	        this.title = title;
121	    }
122	
123	    /**
124	     * Derive the owner's read-only {@code salutation}: the honorific {@code title} and
125	     * {@code lastName} joined by a single space ({@code '<title> <lastName>'}) when a title has
126	     * been supplied, otherwise just the {@code lastName}. A {@code null} or blank title yields the
127	     * bare last name.
128	     */
129	    @Transient
130	    public String getSalutation() {
131	        if (this.title == null || this.title.isBlank()) {
132	            return getLastName();
133	        }
134	        return this.title + " " + getLastName();
135	    }
136	
137	    public String getAddress() {
138	        return this.address;
139	    }
140	
141	    public void setAddress(String address) {
142	        this.address = address;
143	    }
144	
145	    public String getAddressLine1() {
146	        return this.addressLine1;
147	    }
148	
149	    public void setAddressLine1(String addressLine1) {
150	        this.addressLine1 = addressLine1;
151	    }
152	
153	    public String getAddressLine2() {
154	        return this.addressLine2;
155	    }
156	
157	    public void setAddressLine2(String addressLine2) {
158	        this.addressLine2 = addressLine2;
159	    }
160	
161	    public String getCity() {
162	        return this.city;
163	    }
164	
165	    public void setCity(String city) {
166	        this.city = city;
167	    }
168	
169	    public String getPostcode() {
170	        return this.postcode;
171	    }
172	
173	    public void setPostcode(String postcode) {
174	        this.postcode = postcode;
175	    }
176	
177	    public String getTelephone() {
178	        return this.telephone;
179	    }
180	
181	    public void setTelephone(String telephone) {
182	        this.telephone = telephone;
183	    }
184	
185	    public String getEmail() {
186	        return this.email;
187	    }
188	
189	    public void setEmail(String email) {
190	        this.email = email;
191	    }
192	
193	    public LocalDate getRegistrationDate() {
194	        return this.registrationDate;
195	    }
196	
197	    public void setRegistrationDate(LocalDate registrationDate) {
198	        this.registrationDate = registrationDate;
199	    }
200	
201	    public LocalDate getBirthDate() {
202	        return this.birthDate;
203	    }
204	
205	    public void setBirthDate(LocalDate birthDate) {
206	        this.birthDate = birthDate;
207	    }
208	
209	    /**
210	     * Derive the owner's read-only {@code ageBand} from {@code birthDate}, computed against the
211	     * owner's {@code registrationDate} (falling back to the current date when no registration date
212	     * has been assigned yet): {@code MINOR} when under 18, {@code ADULT} from 18 to 64 inclusive,
213	     * {@code SENIOR} at 65 or older. Returns {@code null} when no {@code birthDate} has been supplied.
214	     */
215	    @Transient
216	    public String getAgeBand() {
217	        if (this.birthDate == null) {
218	            return null;
219	        }
220	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
221	        int age = Period.between(this.birthDate, reference).getYears();
222	        if (age < 18) {
223	            return "MINOR";
224	        }
225	        if (age < 65) {
226	            return "ADULT";
227	        }
228	        return "SENIOR";
229	    }
230	
231	    public String getCustomerCode() {
232	        return this.customerCode;
233	    }
234	
235	    public void setCustomerCode(String customerCode) {
236	        this.customerCode = customerCode;
237	    }
238	
239	    public String getMembershipNumber() {
240	        return this.membershipNumber;
241	    }
242	
243	    public void setMembershipNumber(String membershipNumber) {
244	        this.membershipNumber = membershipNumber;
245	    }
246	
247	    public String getHouseholdId() {
248	        return this.householdId;
249	    }
250	
251	    public void setHouseholdId(String householdId) {
252	        this.householdId = householdId;
253	    }
254	
255	    public Integer getNamesakeCount() {
256	        return this.namesakeCount;
257	    }
258	
259	    public void setNamesakeCount(Integer namesakeCount) {
260	        this.namesakeCount = namesakeCount;
261	    }
262	
263	    /**
264	     * Derive the owner's {@code membershipPoints}: a score starting at 0 that adds 2 when an email
265	     * is present, adds 1 when the owner's name was unique at creation time ({@code namesakeCount}
266	     * is 0), adds 2 when the owner belongs to a household of three or more members, and adds 3 when
267	     * the owner's tenure is at least one elapsed fiscal year (measured from the
268	     * {@code registrationDate} to today, where the fiscal year starts on 1 July).
269	     */
270	    @Transient
271	    public Integer getMembershipPoints() {
272	        int points = 0;
273	        if (this.email != null && !this.email.isBlank()) {
274	            points += 2;
275	        }
276	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
277	            points += 1;
278	        }
279	        if (this.householdMemberCount != null && this.householdMemberCount >= 3) {
280	            points += 2;
281	        }
282	        if (hasTenureOverOneFiscalYear()) {
283	            points += 3;
284	        }
285	        return points;
286	    }
287	
288	    /**
289	     * Derive the owner's numeric {@code membershipLevel}, from 1 to 4, by mapping the owner's
290	     * {@code membershipPoints}: level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5
291	     * points, and level 4 for 6 or more points.
292	     */
293	    @Transient
294	    public Integer getMembershipLevel() {
295	        int points = getMembershipPoints();
296	        if (points <= 1) {
297	            return 1;
298	        }
299	        if (points <= 3) {
300	            return 2;
301	        }
302	        if (points <= 5) {
303	            return 3;
304	        }
305	        return 4;
306	    }
307	
308	    /**
309	     * Whether the owner's tenure, measured as the number of elapsed fiscal years from
310	     * {@code registrationDate} to today (the fiscal year starting on 1 July), is at least one —
311	     * worth 3 membership points. A missing {@code registrationDate} (and therefore zero tenure)
312	     * never qualifies.
313	     */
314	    @Transient
315	    private boolean hasTenureOverOneFiscalYear() {
316	        if (this.registrationDate == null) {
317	            return false;
318	        }
319	        return fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate) >= 1;
320	    }
321	
322	    /**
323	     * Derive the owner's read-only {@code fiscalYear}: {@code 'FY<YY>'} where YY is the last two
324	     * digits of the fiscal year of the owner's business-day-adjusted {@code registrationDate}. The
325	     * fiscal year starts on 1 July, so a registration on or after 1 July belongs to the fiscal year
326	     * ending the following 30 June. Returns {@code null} when no {@code registrationDate} has been
327	     * assigned yet, so the field is omitted from the response.
328	     */
329	    @Transient
330	    public String getFiscalYear() {
331	        if (this.registrationDate == null) {
332	            return null;
333	        }
334	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
335	    }
336	
337	    /**
338	     * The fiscal year a {@code date} falls in, identified by its ending calendar year. The fiscal
339	     * year starts on 1 July, so dates on or after 1 July belong to the following year's fiscal year
340	     * (e.g. 1 July 2026 is fiscal year 2027), while dates from 1 January to 30 June belong to the
341	     * current year's fiscal year.
342	     */
343	    public static int fiscalYearOf(LocalDate date) {
344	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
345	    }
346	
347	    /**
348	     * Derive the owner's read-only {@code checkDigit}: a single Luhn check digit (0-9) computed
349	     * over the digits contained in the owner's {@code customerCode}. Non-digit characters (the
350	     * '-' separators and letters) are ignored. Returns {@code null} when no {@code customerCode}
351	     * has been assigned yet.
352	     */
353	    @Transient
354	    public Integer getCheckDigit() {
355	        if (this.customerCode == null) {
356	            return null;
357	        }
358	        int sum = 0;
359	        boolean dbl = true;
360	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
361	            char c = this.customerCode.charAt(i);
362	            if (c < '0' || c > '9') {
363	                continue;
364	            }
365	            int d = c - '0';
366	            if (dbl) {
367	                d *= 2;
368	                if (d > 9) {
369	                    d -= 9;
370	                }
371	            }
372	            sum += d;
373	            dbl = !dbl;
374	        }
375	        return (10 - (sum % 10)) % 10;
376	    }
377	
378	    /**
379	     * Derive the owner's {@code identityKey}, the single value used to detect duplicate owners:
380	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. The telephone and
381	     * email are already stored in their canonical (E.164 / lower-cased) form, so a {@code null} or
382	     * blank email contributes an empty segment and an absent {@code householdId} an empty segment.
383	     * Two owners are duplicates only when their whole {@code identityKey} is equal.
384	     */
385	    @Transient
386	    public String getIdentityKey() {
387	        String telephonePart = this.telephone == null ? "" : this.telephone;
388	        String emailPart = (this.email == null || this.email.isBlank()) ? "" : this.email;
389	        String householdPart = this.householdId == null ? "" : this.householdId;
390	        return telephonePart + "|" + emailPart + "|" + householdPart;
391	    }
392	
393	    public boolean isBulkSignupWarning() {
394	        return this.bulkSignupWarning;
395	    }
396	
397	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
398	        this.bulkSignupWarning = bulkSignupWarning;
399	    }
400	
401	    public Integer getHouseholdMemberCount() {
402	        return this.householdMemberCount;
403	    }
404	
405	    public void setHouseholdMemberCount(Integer householdMemberCount) {
406	        this.householdMemberCount = householdMemberCount;
407	    }
408	
409	    /**
410	     * Whether this owner was flagged at creation as a possible (soft) duplicate: it is not a hard
411	     * {@code identityKey} duplicate, but shares an existing owner's last name and postcode while
412	     * carrying a different telephone. The owner is still created; this flag is advisory.
413	     */
414	    public boolean isPossibleDuplicate() {
415	        return this.possibleDuplicate;
416	    }
417	
418	    public void setPossibleDuplicate(boolean possibleDuplicate) {
419	        this.possibleDuplicate = possibleDuplicate;
420	    }
421	
422	    /**
423	     * The id of the existing owner this one soft-matched against (same last name and postcode,
424	     * different telephone), or {@code null} when {@link #isPossibleDuplicate()} is {@code false}.
425	     */
426	    public Integer getPossibleDuplicateOf() {
427	        return this.possibleDuplicateOf;
428	    }
429	
430	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
431	        this.possibleDuplicateOf = possibleDuplicateOf;
432	    }
433	
434	    /**
435	     * Whether this owner has been soft-deleted: DELETE /api/owners/{id} sets this flag rather than
436	     * removing the row, so the owner is retained and still readable but is ignored by the create
437	     * endpoint's duplicate and identity checks. A newly created owner is not deleted.
438	     */
439	    public boolean isDeleted() {
440	        return this.deleted;
441	    }
442	
443	    public void setDeleted(boolean deleted) {
444	        this.deleted = deleted;
445	    }
446	
447	    /**
448	     * The {@code Idempotency-Key} the owner was first created under, or {@code null} when the create
449	     * carried no such header. When a create repeats with an already-seen key, the originally created
450	     * owner is returned instead of a duplicate being created, so the key is retained to recognise the
451	     * repeat.
452	     */
453	    public String getIdempotencyKey() {
454	        return this.idempotencyKey;
455	    }
456	
457	    public void setIdempotencyKey(String idempotencyKey) {
458	        this.idempotencyKey = idempotencyKey;
459	    }
460	
461	    public boolean isSharesHousehold() {
462	        return this.sharesHousehold;
463	    }
464	
465	    public void setSharesHousehold(boolean sharesHousehold) {
466	        this.sharesHousehold = sharesHousehold;
467	    }
468	
469	    protected Set<Pet> getPetsInternal() {
470	        if (this.pets == null) {
471	            this.pets = new HashSet<>();
472	        }
473	        return this.pets;
474	    }
475	
476	    protected void setPetsInternal(Set<Pet> pets) {
477	        this.pets = pets;
478	    }
479	
480	    public List<Pet> getPets() {
481	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
482	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
483	        return Collections.unmodifiableList(sortedPets);
484	    }
485	
486	    public void setPets(List<Pet> pets) {
487	        this.pets = new HashSet<>(pets);
488	    }
489	
490	    public void addPet(Pet pet) {
491	        getPetsInternal().add(pet);
492	        pet.setOwner(this);
493	    }
494	
495	    /**
496	     * Return the Pet with the given name, or null if none found for this Owner.
497	     *
498	     * @param name to test
499	     * @return true if pet name is already in use
500	     */
501	    public Pet getPet(String name) {
502	        return getPet(name, false);
503	    }
504	
505	    /**
506	     * Return the Pet with the given name, or null if none found for this Owner.
507	     *
508	     * @param name to test
509	     * @return true if pet name is already in use
510	     */
511	    public Pet getPet(String name, boolean ignoreNew) {
512	        name = name.toLowerCase();
513	        for (Pet pet : getPetsInternal()) {
514	            if (!ignoreNew || !pet.isNew()) {
515	                String compName = pet.getName();
516	                compName = compName.toLowerCase();
517	                if (compName.equals(name)) {
518	                    return pet;
519	                }
520	            }
521	        }
522	        return null;
523	    }
524	
525	    public Pet getPet(Integer petId) {
526	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
527	    }
528	
529	    @Override
530	    public String toString() {
531	        return new ToStringCreator(this)
532	
533	            .append("id", this.getId())
534	            .append("new", this.isNew())
535	            .append("lastName", this.getLastName())
536	            .append("firstName", this.getFirstName())
537	            .append("address", this.address)
538	            .append("city", this.city)
539	            .append("telephone", this.telephone)
540	            .toString();
541	    }
542	}
