337	     * owner. The key consolidates telephone, email and household into one value, so two owners
338	     * collide only when their whole key is equal (see {@link Owner#getIdentityKey()}). By this point
339	     * the owner's {@code householdId} has been resolved, so its key is complete.
340	     */
341	    private boolean isIdentityKeyAlreadyUsed(Owner owner) {
342	        String identityKey = owner.getIdentityKey();
343	        return ownerRepository.findAll().stream()
344	            .filter(existing -> !existing.isDeleted())
345	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
