369	    /**
370	     * Count the owners that already exist (before this create) sharing the same first name and last
371	     * name as {@code owner}, compared case-insensitively. Returns zero when the owner's name is
372	     * unique among the existing owners.
373	     */
374	    private int countNamesakes(Owner owner) {
375	        String firstName = owner.getFirstName();
376	        String lastName = owner.getLastName();
377	        if (firstName == null || lastName == null) {
378	            return 0;
379	        }
380	        return (int) ownerRepository.findAll().stream()
381	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
382	                && lastName.equalsIgnoreCase(existing.getLastName()))
383	            .count();
384	    }
