386	    /**
387	     * Find the owners that already belong to the same household as {@code owner}, i.e. share both its
388	     * last name and its postcode. Last names are compared case-insensitively with collapsed
389	     * whitespace; postcodes are compared exactly. This is the same keying used by
390	     * {@link #computeHouseholdId(Owner)}, so these are exactly the existing owners that carry the
391	     * owner's computed {@code householdId}. Returns an empty list when the owner has no last name or
392	     * postcode to match on.
393	     */
394	    private List<Owner> findHouseholdMembers(Owner owner) {
395	        String key = householdKey(owner);
396	        if (key == null) {
397	            return List.of();
398	        }
399	        return ownerRepository.findAll().stream()
400	            .filter(existing -> !existing.isDeleted())
401	            .filter(existing -> key.equals(householdKey(existing)))
402	            .toList();
403	    }
