201	        ownerPageDto.setPage(ownerPage.getNumber());
202	        ownerPageDto.setSize(ownerPage.getSize());
203	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
204	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
205	        return ownerPageDto;
206	    }
